export default async function select({ messages, acknowledge }, ctx) {
  const key = "outlook-category-active",
    old = await ctx.state.get(key);
  if (old) {
    if (acknowledge !== old.id)
      throw Error(
        "Inspect Outlook message " +
          old.id +
          " and complete any missing action manually before acknowledging",
      );
    await ctx.state.set(key, null);
  }
  const m = messages?.[0];
  if (!m) return { has: false, id: "", prompt: "", read: false };
  if (
    !m.id ||
    m.flag?.flagStatus !== "notFlagged" ||
    !Array.isArray(m.categories) ||
    m.categories.length
  )
    throw Error("Message does not match unflagged and uncategorized filter");
  return {
    has: true,
    id: m.id,
    prompt: JSON.stringify({
      subject: m.subject,
      body: m.body,
      from: m.from,
      sender: m.sender,
      importance: m.importance,
    }),
    read: !!m.isRead,
  };
}

