export default async function plan(
  { id, read, answer, junk, receipt, saas, community, actioned },
  ctx,
) {
  const cats = ["action", "junk", "receipt", "saas", "community", "business", "other"],
    c = answer.category?.toLowerCase(),
    s = answer.subCategory?.toLowerCase() || "";
  if (!cats.includes(c) || (s && !cats.includes(s))) throw Error("Invalid classification");
  const names = [c, s]
    .filter(Boolean)
    .map((x) => (x === "saas" ? "SaaS" : x[0].toUpperCase() + x.slice(1)));
  const dest =
    { junk, receipt, saas, community }[c] ||
    ((c === "action" || c === "business") && read ? actioned : "");
  if (dest && dest.includes("YOUR_")) throw Error("Configure folder ID");
  await ctx.state.set("outlook-category-active", {
    id,
    stage: "category",
    categories: names,
    destination: dest,
  });
  return {
    endpoint: "/me/messages/" + encodeURIComponent(id),
    body: { categories: names },
    dest,
    id,
  };
}

