export default async function after({ id, dest, statusCode }, ctx) {
  if (statusCode < 200 || statusCode >= 300) throw Error("Category update unknown: inspect " + id);
  if (dest)
    await ctx.state.set("outlook-category-active", { id, stage: "move", destination: dest });
  else await ctx.state.set("outlook-category-active", null);
  return {
    move: !!dest,
    endpoint: "/me/messages/" + encodeURIComponent(id) + "/move",
    body: { destinationId: dest },
  };
}

